fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Precondition: `a` and `b` must have the same length.
    assert_eq!(a.len(), b.len());

    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x >= y)
     .collect()
}

